import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'
import { IntegerColumn } from '@servicenow/sdk/core'

export const flowForEachNested = Flow(
    {
        $id: Now.ID['foreach-nested'],
        name: 'ForEach Nested',
        description: 'A testing',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        flowVariables: {
            counter: IntegerColumn({
                label: 'Counter',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['foreach-nested-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.flowLogic.forEach(
            wfa.dataPill(params.trigger.current.watch_list, 'array.string'),
            {
                $id: Now.ID['foreach-nested-loop'],
                annotation: 'Processing each user in watch list',
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['foreach-nested-log'],
                    },
                    {
                        log_level: 'info',
                        log_message: 'Processing user from watch list',
                    }
                )
                // Nested ForEach for additional_assignee_list
                wfa.flowLogic.forEach(
                    wfa.dataPill(params.trigger.current.additional_assignee_list, 'array.string'),
                    {
                        $id: Now.ID['foreach-nested-assignee-loop'],
                        annotation: 'Processing each additional assignee',
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['foreach-nested-assignee-log'],
                            },
                            {
                                log_level: 'info',
                                log_message: 'Processing additional assignee',
                            }
                        )
                    }
                )
            }
        )
    }
)
